cd wheelhouse && python3 - <<'EOF'
import zipfile, glob, re
for w in sorted(glob.glob('*.whl')):
    print("="*60)
    print(w)
    with zipfile.ZipFile(w) as z:
        for n in z.namelist():
            print("  ", n)
        for n in z.namelist():
            if n.endswith('METADATA') or n.endswith('WHEEL') or n.endswith('RECORD') or n.endswith('entry_points.txt'):
                print("-"*40, n)
                print(z.read(n).decode('utf-8', 'replace'))
EOF
